using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Mbb.Archive.Modules.Retention.Domain.Cases;using Mbb.Archive.Modules.Retention.Domain.Rules;
namespace Mbb.Archive.Modules.Retention.Infrastructure.Persistence.Configurations;
internal sealed class RuleConfig:IEntityTypeConfiguration<RetentionRule>{public void Configure(EntityTypeBuilder<RetentionRule>b){b.ToTable("rules","retention");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(100);b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(300);b.Property(x=>x.RetentionMonths).HasColumnName("retention_months");b.Property(x=>x.Action).HasColumnName("action").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.HasIndex(x=>x.Code).IsUnique();}}
internal sealed class CaseConfig:IEntityTypeConfiguration<RetentionCase>{public void Configure(EntityTypeBuilder<RetentionCase>b){b.ToTable("cases","retention");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.ArchiveRecordId).HasColumnName("archive_record_id");b.Property(x=>x.DocumentId).HasColumnName("document_id");b.Property(x=>x.RuleId).HasColumnName("rule_id");b.Property(x=>x.RuleCode).HasColumnName("rule_code").HasMaxLength(100);b.Property(x=>x.Action).HasColumnName("action").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.TriggerAt).HasColumnName("trigger_at");b.Property(x=>x.DueAt).HasColumnName("due_at");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.ActiveHoldCount).HasColumnName("active_hold_count");b.Property(x=>x.ConcurrencyVersion).HasColumnName("concurrency_version").IsConcurrencyToken();b.Ignore(x=>x.DomainEvents);b.HasIndex(x=>x.ArchiveRecordId).IsUnique();b.HasIndex(x=>new{x.Status,x.DueAt});}}
internal sealed class HoldConfig:IEntityTypeConfiguration<LegalHold>{public void Configure(EntityTypeBuilder<LegalHold>b){b.ToTable("legal_holds","retention");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.RetentionCaseId).HasColumnName("retention_case_id");b.Property(x=>x.ArchiveRecordId).HasColumnName("archive_record_id");b.Property(x=>x.Reason).HasColumnName("reason").HasMaxLength(2000);b.Property(x=>x.PlacedBy).HasColumnName("placed_by").HasMaxLength(300);b.Property(x=>x.PlacedAt).HasColumnName("placed_at");b.Property(x=>x.ReleasedAt).HasColumnName("released_at");b.Property(x=>x.ReleasedBy).HasColumnName("released_by").HasMaxLength(300);b.Property(x=>x.ReleaseReason).HasColumnName("release_reason").HasMaxLength(2000);b.Ignore(x=>x.IsActive);b.Ignore(x=>x.DomainEvents);b.HasIndex(x=>new{x.RetentionCaseId,x.ReleasedAt});}}
internal sealed class InboxConfig:IEntityTypeConfiguration<InboxMessage>{public void Configure(EntityTypeBuilder<InboxMessage>b){b.ToTable("inbox_messages","retention");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.EventName).HasColumnName("event_name").HasMaxLength(200);b.Property(x=>x.ProcessedAt).HasColumnName("processed_at");}}
internal sealed class OutboxConfig:IEntityTypeConfiguration<OutboxMessage>{public void Configure(EntityTypeBuilder<OutboxMessage>b){b.ToTable("outbox_messages","retention");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.EventName).HasColumnName("event_name").HasMaxLength(200);b.Property(x=>x.Payload).HasColumnName("payload").HasColumnType("jsonb");b.Property(x=>x.OccurredAt).HasColumnName("occurred_at");b.Property(x=>x.NextAttemptAt).HasColumnName("next_attempt_at");b.Property(x=>x.ProcessedAt).HasColumnName("processed_at");b.Property(x=>x.DeadLetteredAt).HasColumnName("dead_lettered_at");b.Property(x=>x.AttemptCount).HasColumnName("attempt_count");b.Property(x=>x.LastError).HasColumnName("last_error").HasMaxLength(4000);b.Property(x=>x.LockedBy).HasColumnName("locked_by").HasMaxLength(200);b.Property(x=>x.LockedUntil).HasColumnName("locked_until");}}
